import{_ as p,a0 as o,w as d,s as h,I as a,x as e,a1 as t,A as l,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"基於 Tmux 的多會話終端管理示例 | LCTT x X-CMD","titleTemplate":false,"description":"基於 Tmux 的多會話終端管理示例 | LCTT (202102) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"基於 Tmux 的多會話終端管理示例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"基於 Tmux 的多會話終端管理示例 | LCTT (202102) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202102/20190610 Tmux Command Examples To Manage Multiple Terminal Sessions","title":"基於 Tmux 的多會話終端管理示例","tag":"202102","desc":""},"relativePath":"202102/20190610 Tmux Command Examples To Manage Multiple Terminal Sessions.md","filePath":"[post].md"}'),r={name:"202102/20190610 Tmux Command Examples To Manage Multiple Terminal Sessions.md"};function u(m,s,c,g,x,b){const i=o("Link");return d(),h("div",null,[s[22]||(s[22]=a("h1",{id:"基於-tmux-的多會話終端管理示例",tabindex:"-1"},[e("基於 Tmux 的多會話終端管理示例 "),a("a",{class:"header-anchor",href:"#基於-tmux-的多會話終端管理示例","aria-label":"Permalink to “基於 Tmux 的多會話終端管理示例”"},"​")],-1)),s[23]||(s[23]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202102/11/101058ffso6wzzw94wm2ng.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("我們已經瞭解到如何通過 ",-1)),t(i,{href:"https://www.ostechnix.com/screen-command-examples-to-manage-multiple-terminal-sessions/"},{default:l(()=>[...s[0]||(s[0]=[e("GNU Screen",-1)])]),_:1}),s[2]||(s[2]=e(" 進行多會話管理。今天，我們將要領略另一個著名的管理會話的命令列實用工具 ",-1)),s[3]||(s[3]=a("strong",null,"Tmux",-1)),s[4]||(s[4]=e("。類似 GNU Screen，Tmux 是一個幫助我們在單一終端窗口中創建多個會話，同一時間內同時運行多個應用程序或進程的終端複用工具。Tmux 自由、開源並且跨平台，支持 Linux、OpenBSD、FreeBSD、NetBSD 以及 Mac OS X。本文將討論 Tmux 在 Linux 系統下的高頻用法。",-1))]),s[24]||(s[24]=n(`<h3 id="linux-下安裝-tmux" tabindex="-1">Linux 下安裝 Tmux <a class="header-anchor" href="#linux-下安裝-tmux" aria-label="Permalink to “Linux 下安裝 Tmux”">​</a></h3><p>Tmux 可以在絕大多數的 Linux 官方倉庫下獲取。</p><p>在 Arch Linux 或它的變種系統下，執行下列命令來安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S tmux</span></span></code></pre></div><p>Debian、Ubuntu 或 Linux Mint：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install tmux</span></span></code></pre></div><p>Fedora：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install tmux</span></span></code></pre></div><p>RHEL 和 CentOS：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install tmux</span></span></code></pre></div><p>SUSE/openSUSE：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo zypper install tmux</span></span></code></pre></div><p>以上，我們已經完成 Tmux 的安裝。之後我們繼續看看一些 Tmux 示例。</p><h3 id="tmux-命令示例-多會話管理" tabindex="-1">Tmux 命令示例: 多會話管理 <a class="header-anchor" href="#tmux-命令示例-多會話管理" aria-label="Permalink to “Tmux 命令示例: 多會話管理”">​</a></h3><p>Tmux 默認所有命令的前置命令都是 <code>Ctrl+b</code>，使用前牢記這個快捷鍵即可。</p><blockquote><p><strong>注意</strong>：<strong>Screen</strong> 的前置命令都是 <code>Ctrl+a</code>.</p></blockquote><h4 id="創建-tmux-會話" tabindex="-1">創建 Tmux 會話 <a class="header-anchor" href="#創建-tmux-會話" aria-label="Permalink to “創建 Tmux 會話”">​</a></h4><p>在終端中運行如下命令創建 Tmux 會話並附着進入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux</span></span></code></pre></div><p>抑或，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux new</span></span></code></pre></div><p>一旦進入 Tmux 會話，你將看到一個 <strong>沉在底部的綠色的邊欄</strong>，如下圖所示。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/Tmux-session.png" alt=""></p><p><em>創建 Tmux 會話</em></p><p>這個綠色的邊欄能很容易提示你當前是否身處 Tmux 會話當中。</p><h4 id="退出-tmux-會話" tabindex="-1">退出 Tmux 會話 <a class="header-anchor" href="#退出-tmux-會話" aria-label="Permalink to “退出 Tmux 會話”">​</a></h4><p>退出當前 Tmux 會話僅需要使用 <code>Ctrl+b</code> 和 <code>d</code>。無需同時觸發這兩個快捷鍵，依次按下 <code>Ctrl+b</code> 和 <code>d</code> 即可。</p><p>退出當前會話後，你將能看到如下輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[detached (from session 0)]</span></span></code></pre></div><h4 id="創建有名會話" tabindex="-1">創建有名會話 <a class="header-anchor" href="#創建有名會話" aria-label="Permalink to “創建有名會話”">​</a></h4><p>如果使用多個會話，你很可能會混淆運行在多個會話中的應用程序。這種情況下，我們需要會話並賦予名稱。譬如需要 web 相關服務的會話，就創建一個名稱為 “webserver”（或任意一個其他名稱） 的 Tmux 會話。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux new -s webserver</span></span></code></pre></div><p>這裏是新的 Tmux 有名會話：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/Named-Tmux-session.png" alt=""></p><p><em>擁有自定義名稱的 Tmux 會話</em></p><p>如你所見上述截圖，這個 Tmux 會話的名稱已經被標註為 “webserver”。如此，你可以在多個會話中，輕易的區分應用程序的所在。</p><p>退出會話，輕按 <code>Ctrl+b</code> 和 <code>d</code>。</p><h4 id="查看-tmux-會話清單" tabindex="-1">查看 Tmux 會話清單 <a class="header-anchor" href="#查看-tmux-會話清單" aria-label="Permalink to “查看 Tmux 會話清單”">​</a></h4><p>查看 Tmux 會話清單，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux ls</span></span></code></pre></div><p>示例輸出：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/List-Tmux-sessions.png" alt=""></p><p><em>列出 Tmux 會話</em></p><p>如你所見，我們開啓了兩個 Tmux 會話。</p><h4 id="創建非附着會話" tabindex="-1">創建非附着會話 <a class="header-anchor" href="#創建非附着會話" aria-label="Permalink to “創建非附着會話”">​</a></h4><p>有時候，你可能想要簡單創建會話，但是並不想自動切入該會話。</p><p>創建一個非附着會話，並賦予名稱 “ostechnix”，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux new -s ostechnix -d</span></span></code></pre></div><p>上述命令將會創建一個名為 “ostechnix” 的會話，但是並不會附着進入。</p><p>你可以通過使用 <code>tmux ls</code> 命令驗證：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/Create-detached-sessions.png" alt=""></p><p><em>創建非附着會話</em></p><h4 id="附着進入-tmux-會話" tabindex="-1">附着進入 Tmux 會話 <a class="header-anchor" href="#附着進入-tmux-會話" aria-label="Permalink to “附着進入 Tmux 會話”">​</a></h4><p>通過如下命令，你可以附着進入最後一個被創建的會話：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux attach</span></span></code></pre></div><p>抑或，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux a</span></span></code></pre></div><p>如果你想附着進入任意一個指定的有名會話，譬如 “ostechnix”，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux attach -t ostechnix</span></span></code></pre></div><p>或者，簡寫為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux a -t ostechnix</span></span></code></pre></div><h4 id="關閉-tmux-會話" tabindex="-1">關閉 Tmux 會話 <a class="header-anchor" href="#關閉-tmux-會話" aria-label="Permalink to “關閉 Tmux 會話”">​</a></h4><p>當你完成或者不再需要 Tmux 會話，你可以通過如下命令關閉：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux kill-session -t ostechnix</span></span></code></pre></div><p>當身處該會話時，使用 <code>Ctrl+b</code> 以及 <code>x</code>。點擊 <code>y</code> 來關閉會話。</p><p>可以通過 <code>tmux ls</code> 命令驗證。</p><p>關閉所有 Tmux 服務下的所有會話，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux kill-server</span></span></code></pre></div><p>謹慎！這將終止所有 Tmux 會話，並不會產生任何警告，即便會話存在運行中的任務。</p><p>如果不存在活躍的 Tmux 會話，將看到如下輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tmux ls</span></span>
<span class="line"><span>no server running on /tmp/tmux-1000/default</span></span></code></pre></div><h4 id="切割-tmux-窗口" tabindex="-1">切割 Tmux 窗口 <a class="header-anchor" href="#切割-tmux-窗口" aria-label="Permalink to “切割 Tmux 窗口”">​</a></h4><p>切割窗口成多個小窗口，在 Tmux 中，這個叫做 “Tmux 窗格”。每個窗格中可以同時運行不同的程序，並同時與所有的窗格進行交互。每個窗格可以在不影響其他窗格的前提下可以調整大小、移動位置和控制關閉。我們可以以水平、垂直或者二者混合的方式切割屏幕。</p><h5 id="水平切割窗格" tabindex="-1">水平切割窗格 <a class="header-anchor" href="#水平切割窗格" aria-label="Permalink to “水平切割窗格”">​</a></h5><p>欲水平切割窗格，使用 <code>Ctrl+b</code> 和 <code>&quot;</code>（半個雙引號）。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/Horizontal-split.png" alt=""></p><p><em>水平切割 Tmux 窗格</em></p><p>可以使用組合鍵進一步切割面板。</p><h5 id="垂直切割窗格" tabindex="-1">垂直切割窗格 <a class="header-anchor" href="#垂直切割窗格" aria-label="Permalink to “垂直切割窗格”">​</a></h5><p>垂直切割面板，使用 <code>Ctrl+b</code> 和 <code>%</code>。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/Vertical-split.png" alt=""></p><p><em>垂直切割 Tmux 窗格</em></p><h5 id="水平、垂直混合切割窗格" tabindex="-1">水平、垂直混合切割窗格 <a class="header-anchor" href="#水平、垂直混合切割窗格" aria-label="Permalink to “水平、垂直混合切割窗格”">​</a></h5><p>我們也可以同時採用水平和垂直的方案切割窗格。看看如下截圖：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/Split-Panes.png" alt=""></p><p><em>切割 Tmux 窗格</em></p><p>首先，我通過 <code>Ctrl+b</code> <code>&quot;</code> 水平切割，之後通過 <code>Ctrl+b</code> <code>%</code> 垂直切割下方的窗格。</p><p>如你所見，每個窗格下我運行了不同的程序。</p><h5 id="切換窗格" tabindex="-1">切換窗格 <a class="header-anchor" href="#切換窗格" aria-label="Permalink to “切換窗格”">​</a></h5><p>通過 <code>Ctrl+b</code> 和方向鍵（上下左右）切換窗格。</p><h5 id="發送命令給所有窗格" tabindex="-1">發送命令給所有窗格 <a class="header-anchor" href="#發送命令給所有窗格" aria-label="Permalink to “發送命令給所有窗格”">​</a></h5><p>之前的案例中，我們在每個窗格中運行了三個不同命令。其實，也可以發送相同的命令給所有窗格。</p><p>為此，使用 <code>Ctrl+b</code> 然後鍵入如下命令，之後按下回車：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:setw synchronize-panes</span></span></code></pre></div><p>現在在任意窗格中鍵入任何命令。你將看到相同命令影響了所有窗格。</p><h5 id="交換窗格" tabindex="-1">交換窗格 <a class="header-anchor" href="#交換窗格" aria-label="Permalink to “交換窗格”">​</a></h5><p>使用 <code>Ctrl+b</code> 和 <code>o</code> 交換窗格。</p><h5 id="展示窗格號" tabindex="-1">展示窗格號 <a class="header-anchor" href="#展示窗格號" aria-label="Permalink to “展示窗格號”">​</a></h5><p>使用 <code>Ctrl+b</code> 和 <code>q</code> 展示窗格號。</p><h5 id="終止窗格" tabindex="-1">終止窗格 <a class="header-anchor" href="#終止窗格" aria-label="Permalink to “終止窗格”">​</a></h5><p>要關閉窗格，直接鍵入 <code>exit</code> 並且按下回車鍵。或者，按下 <code>Ctrl+b</code> 和 <code>x</code>。你會看到確認信息。按下 <code>y</code> 關閉窗格。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/Kill-panes.png" alt=""></p><p><em>關閉窗格</em></p><h5 id="放大和縮小-tmux-窗格" tabindex="-1">放大和縮小 Tmux 窗格 <a class="header-anchor" href="#放大和縮小-tmux-窗格" aria-label="Permalink to “放大和縮小 Tmux 窗格”">​</a></h5><p>我們可以將 Tmux 窗格放大到當前終端窗口的全尺寸，以獲得更好的文本可視性，並查看更多的內容。當你需要更多的空間或專注於某個特定的任務時，這很有用。在完成該任務後，你可以將 Tmux 窗格縮小（取消放大）到其正常位置。更多詳情請看以下鏈接。</p>`,105)),a("ul",null,[a("li",null,[t(i,{href:"https://ostechnix.com/how-to-zoom-tmux-panes-for-better-text-visibility/"},{default:l(()=>[...s[5]||(s[5]=[e("如何縮放 Tmux 窗格以提高文本可見度？",-1)])]),_:1})])]),s[25]||(s[25]=a("h4",{id:"自動啓動-tmux-會話",tabindex:"-1"},[e("自動啓動 Tmux 會話 "),a("a",{class:"header-anchor",href:"#自動啓動-tmux-會話","aria-label":"Permalink to “自動啓動 Tmux 會話”"},"​")],-1)),s[26]||(s[26]=a("p",null,"當通過 SSH 與遠程系統工作時，在 Tmux 會話中運行一個長期運行的進程總是一個好的做法。因為，它可以防止你在網絡連接突然中斷時失去對運行進程的控制。避免這個問題的一個方法是自動啓動 Tmux 會話。更多詳情，請參考以下鏈接。",-1)),a("ul",null,[a("li",null,[t(i,{href:"https://ostechnix.com/autostart-tmux-session-on-remote-system-when-logging-in-via-ssh/"},{default:l(()=>[...s[6]||(s[6]=[e("通過 SSH 登錄遠程系統時自動啓動 Tmux 會話",-1)])]),_:1})])]),s[27]||(s[27]=n('<h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>這個階段下，你已經獲得了基本的 Tmux 技能來進行多會話管理，更多細節，參閲 man 頁面。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man tmux</span></span></code></pre></div><p>GNU Screen 和 Tmux 工具都能透過 SSH 很好的管理遠程服務器。學習 Screen 和 Tmux 命令，像個行家一樣，徹底通過這些工具管理遠程服務器。</p><hr>',5)),a("p",null,[s[8]||(s[8]=e("via: ",-1)),t(i,{href:"https://www.ostechnix.com/tmux-command-examples-to-manage-multiple-terminal-sessions/"},{default:l(()=>[...s[7]||(s[7]=[e("https://www.ostechnix.com/tmux-command-examples-to-manage-multiple-terminal-sessions/",-1)])]),_:1})]),a("p",null,[s[13]||(s[13]=e("作者：",-1)),t(i,{href:"https://www.ostechnix.com/author/sk/"},{default:l(()=>[...s[9]||(s[9]=[e("sk",-1)])]),_:1}),s[14]||(s[14]=e(" 選題：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[10]||(s[10]=[e("lujun9972",-1)])]),_:1}),s[15]||(s[15]=e(" 譯者：",-1)),t(i,{href:"https://github.com/chensanle"},{default:l(()=>[...s[11]||(s[11]=[e("chensanle",-1)])]),_:1}),s[16]||(s[16]=e(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[12]||(s[12]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[19]||(s[19]=e("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[17]||(s[17]=[e("LCTT",-1)])]),_:1}),s[20]||(s[20]=e(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:l(()=>[...s[18]||(s[18]=[e("Linux中國",-1)])]),_:1}),s[21]||(s[21]=e(" 榮譽推出",-1))])])}const C=p(r,[["render",u]]);export{T as __pageData,C as default};
